 [['Pattern','A 把 object + verb + result','A把B+动词+结果'],['Put somewhere','把书放在桌子上','把书放在桌子上'],['Finish','把作业做完','把作业做完'],['Negative: 没 goes before 把','没把门关上','没把门关上']],
